function procesarInformacion(datos) {
    console.log("Procesando informacion...");
    console.log("Cantidad de elementos:", datos.length);

    for (let i = 0; i < datos.length; i++) {
        const elemento = datos[i];

        if (elemento.activo) {
            console.log("Elemento activo:", elemento.nombre);
        }
    }

    return datos.filter(elemento => elemento.activo);
}

